      "tool_enrichment": {
        "timeline_context": "Occurred at 2020-10-19 10:46:42, preceding all other suspicious actions.",
        "other_context": "No additional context needed."
      }
    },
    {
      "event_id": "4688",
      "event_description": "Process creation: reg.exe added HKCU\\Environment\\UserInitMprLogonScript pointing to C:\\Users\\wardog\\AppData\\Local\\Temp\\art.bat.",
      "why_abnormal": "Use of reg.exe to modify UserInitMprLogonScript creates a persistence mechanism that runs a script at user logon. This is a known technique for malware persistence.",
      "severity": "CRITICAL",
      "indicators": ["reg.exe", "UserInitMprLogonScript", "art.bat", "EventID 4688"],
      "tool_enrichment": {
        "timeline_context": "Executed at 2020-10-19 10:47:08.745, shortly after the audit log was cleared.",
        "decoded_command": "REG.exe  ADD HKCU\\Environment /v UserInitMprLogonScript /t REG_SZ /d C:\\Users\\wardog\\AppData\\Local\\Temp\\art.bat /f",
        "other_context": "Creator process was cmd.exe (PID 0x2284)."
      }
    },
    {
      "event_id": "4689",
      "event_description": "Process exit: reg.exe terminated with exit status 0x0.",
      "why_abnormal": "Confirms the successful completion of the registry modification step.",
      "severity": "MEDIUM",
      "indicators": ["reg.exe exit", "EventID 4689"],
      "tool_enrichment": {
        "timeline_context": "Occurred immediately after the 4688 event (2020-10-19 10:47:08.771)."
      }
    },
    {
      "event_id": "5156",
      "event_description": "Windows Filtering Platform permitted an outbound TCP connection from windowsazureguestagent.exe (PID 3428) to 168.63.129.16:80.",
      "why_abnormal": "Repeated outbound connections to the Azure metadata service may be benign for Azure VMs, but in the context of log tampering and persistence setup, they warrant investigation for possible C2 or data exfiltration.",
      "severity": "MEDIUM",
      "indicators": ["Outbound connection", "168.63.129.16", "EventID 5156"],
      "tool_enrichment": {
        "timeline_context": "First observed at 2020-10-19 10:46:46.118, continues throughout the log period."
      }
    },
    {
      "event_id": "5158",
      "event_description": "Windows Filtering Platform permitted a bind to a local port for windowsazureguestagent.exe (PID 3428).",
      "why_abnormal": "Binding to local ports is part of normal agent behavior, but combined with the outbound connections and other malicious indicators, it suggests the agent may be leveraged by an attacker.",
      "severity": "LOW",
      "indicators": ["Bind to local port", "EventID 5158"],
      "tool_enrichment": {
        "timeline_context": "First observed at 2020-10-19 10:46:46.118, repeats for multiple processes."
      }
    }
  ]
}

